"""Generate additive standard finance DocTypes; never runs a site migration."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]/'fieldpulse/fieldpulse/doctype'

def f(name,label,kind='Data',**kw):return dict(fieldname=name,label=label,fieldtype=kind,**kw)
def link(name,label,dt,**kw):return f(name,label,'Link',options=dt,**kw)
def select(name,label,options,**kw):return f(name,label,'Select',options='\n'.join(options),**kw)
def amount(name,label,**kw):return f(name,label,'Currency',options='currency',precision='2',**kw)
def state(options):return select('status','Status',options,default=options[0],read_only=1,in_list_view=1)
def audit_fields():return [link('approved_by','Approved by','User',read_only=1),f('approved_at','Approved at','Datetime',read_only=1)]
def evidence():return [f('evidence','Private supporting evidence','Attach'),f('alternative_evidence','Authorised alternative evidence / reference','Small Text')]
def schema(name,fields,*,child=False,coordinator=False,scout=False,single=False):
 slug=name.lower().replace(' ','_');path=ROOT/slug;path.mkdir(exist_ok=True)
 permissions=[] if child else [dict(role=role,read=1,report=1,**({'create':1,'write':1} if role in {'Finance','System Manager'} else {})) for role in ['Finance','System Manager']+(['Field Operations Coordinator'] if coordinator else [])]
 if scout:permissions.append(dict(role='Field Agent',read=1))
 data=dict(protect_attached_files=1,make_attachments_public=0,doctype='DocType',name=name,module='FieldPulse',fields=fields,field_order=[v['fieldname'] for v in fields],permissions=permissions,track_changes=1)
 if child:data['istable']=1;data['editable_grid']=1
 else:data['autoname']='format:'+''.join(w[0] for w in name.split())+'-{#####}';data['title_field']='title' if any(v['fieldname']=='title' for v in fields) else 'name'
 (path/(slug+'.json')).write_text(json.dumps(data,indent=2)+'\n',encoding='utf-8');(path/'__init__.py').write_text('')
 base='Document' if child else 'FinanceDocument'
 imports='from frappe.model.document import Document' if child else 'from fieldpulse.finance_documents import FinanceDocument'
 (path/(slug+'.py')).write_text(imports+'\n\n\nclass '+name.replace(' ','')+'('+base+'):\n    pass\n',encoding='utf-8')
 if not child:
  (path/(slug+'.js')).write_text("frappe.ui.form.on("+json.dumps(name)+", {refresh(frm) {fieldpulse_finance_form(frm);}});\n",encoding='utf-8')

