schema('DD Scout Expense',[link('offer','Accepted arrangement','DD Scout Offer',reqd=1,in_list_view=1),f('client_uuid','Client request ID',unique=1),state(['Draft','Submitted','Approved','Rejected']),select('kind','Expense type',['Travel','Expense'],reqd=1),f('currency','Currency',read_only=1),amount('amount','Claimed amount',reqd=1),f('description','Expense and business purpose','Small Text',reqd=1),*evidence(),f('review_notes','Approval / rejection reason','Small Text'),*audit_fields()],coordinator=True,scout=True)
